import{_ as n,l as s,o as a,c as i,v as r,p as l,x as o,d as p,i as d,S as B}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"DeepSeek-Coder-V2","description":"","frontmatter":{"title":"DeepSeek-Coder-V2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deepseek-coder-v2.md","filePath":"llm/deepseek-coder-v2.md","lastUpdated":1789023840000}'),E={name:"llm/deepseek-coder-v2.md"};function h(A,e,c,m,u,V){const t=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="deepseek-coder-v2" tabindex="-1">DeepSeek-Coder-V2 <a class="header-anchor" href="#deepseek-coder-v2" aria-label="Permalink to &quot;DeepSeek-Coder-V2&quot;">​</a></h1><div class="epigraph"><p>从 DeepSeek-V2 的中间检查点再吃 6 万亿 token：语言从 86 种扩到 338 种，窗口 16K 到 128K，用编译器反馈做 GRPO，开源 MoE 对上 GPT-4 Turbo 一档的代码与数学。</p><footer>—— Zhu 等，DeepSeek-Coder-V2: Breaking the Barrier of Closed-Source Models in Code Intelligence，arXiv:2406.11931</footer></div><p>DeepSeek-Coder-V2 不再从零训稠密代码模型，而是接在 <a href="/llm/deepseek-v2">DeepSeek-V2</a> 中间权重上 <strong>继续预训练 6T</strong>（连同 V2 已见过的约 4.2T，报告合计约 <strong>10.2T</strong>）。架构继承 V2 的 <a href="/llm/mla-kv">MLA</a> 与 <a href="/llm/deepseek-moe">DeepSeekMoE</a>：开源 <strong>Lite 16B（激活约 2.4B）</strong> 与 <strong>236B（激活约 21B）</strong> 的 Base/Instruct，上下文 <strong>128K</strong>。语言从 Coder-V1 的 86 种扩到 <strong>338 种</strong>。本篇写 Zhu 等人的<strong>继续预训练配比、对齐与评测主张</strong>，MLA 路由与共享专家不整段复制 V2 专文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开源 Coder-33B 仍明显落后 GPT-4 Turbo、Claude 3 Opus、Gemini 1.5 Pro。把 33B 稠密再加宽，训练与 KV 都贵；从零再造 200B 级代码模型，重复支付通用语言能力的账单。V2 已经用 MLA 把 KV 压小、用细粒度 MoE 把激活维持在约 21B，中间检查点同时具备通识与长窗潜力。缺口在<strong>代码与数学的密度</strong>：V2 通用配比不够「像代码模型」，V1 又没有 128K 与 300+ 语言。</p><p>继续预训练还要防止通识回退——纯代码 6T 可能把 MMLU 与对话打崩。Lite 要在 2.4B 激活上保留补全（FIM），236B 则面临 FIM 与满参数 NTP 的成本权衡。对齐阶段仅 SFT 不足以让竞赛代码稳定过测例，需要把<strong>编译器与测试</strong>接进强化学习。</p><h3 id="中间检查点-而不是-v2-成品再蒸馏" tabindex="-1">中间检查点，而不是 V2 成品再蒸馏 <a class="header-anchor" href="#中间检查点-而不是-v2-成品再蒸馏" aria-label="Permalink to &quot;中间检查点，而不是 V2 成品再蒸馏&quot;">​</a></h3><p>报告写明：从 <strong>DeepSeek-V2 的 intermediate checkpoint</strong> 继续训，不是把已对齐的 V2-Chat 再蒸馏成代码模型。这样语言建模头与专家仍处在预训练分布，6T 代码–数学–文本混合可以直接接 Adam 式继续训。消融用 1B 稠密验证新代码库：HumanEval 30.5→37.2，MBPP 44.6→54.0。</p><p><span class="marginnote">Lite 与 236B 共享 MoE 设计语言，不共享「是否 FIM」。报告：16B Lite 在对齐阶段仍用 FIM 以保留补全；236B 继续预训练以 NTP 为主。不要假设两档 Instruct 都能当 IDE 中段补全后端。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>继续预训练混合：<strong>60% 源码、10% 数学、30% 自然语言</strong>。源码约 1170B token，GitHub 截止 2023 年 11 月，过滤与近去重沿用 V1 管线，语言扩到 338。数学约 221B，用与 DeepSeekMath 相同的召回管线从 Common Crawl 取，大约是 DeepSeekMath 120B 的两倍。自然语言直接从 V2 语料抽样，承接通识。相对 V1 的 87/10/3，V2 把中英通识提到 30%，并单列 10% 数学——这是「代码模型也要会竞赛数学、还要能聊天」的配比声明。</p><p>上下文 16K→128K，报告写明用 YaRN 一类外推配合长上下文训练，使仓库与长文件进得去。结构上第一层 FFN 稠密、其余 MoE 等设定跟 V2，不在此重写专家数表。</p><p>对齐先 SFT：指令集混合 V1 的代码数据、DeepSeekMath 的数学数据、V2 的通用指令。再 <strong>GRPO</strong>（算法见 <a href="/llm/grpo">GRPO</a> 与 DeepSeekMath）：代码域用编译器反馈与测试构造偏好，训练奖励模型引导策略，使回答对测例负责。这是相对 V1 纯 SFT Instruct 的主差分。</p>',13)),(a(),l(B,null,{default:o(()=>[d(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20V2%5B%22DeepSeek-V2%20%E4%B8%AD%E9%97%B4%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20CPT%5B%22%E7%BB%A7%E7%BB%AD%E9%A2%84%E8%AE%AD%E7%BB%83%206T%22%5D%0A%20%20C%5B%22%E4%BB%A3%E7%A0%81%2060%25%20%C2%B7%20338%20%E8%AF%AD%22%5D%20--%3E%20CPT%0A%20%20M%5B%22%E6%95%B0%E5%AD%A6%2010%25%20%C2%B7%20~221B%22%5D%20--%3E%20CPT%0A%20%20N%5B%22V2%20%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%2030%25%22%5D%20--%3E%20CPT%0A%20%20CPT%20--%3E%20SFT%5B%22SFT%EF%BC%9A%E4%BB%A3%E7%A0%81%20%2B%20%E6%95%B0%E5%AD%A6%20%2B%20%E9%80%9A%E7%94%A8%22%5D%0A%20%20SFT%20--%3E%20GRPO%5B%22GRPO%EF%BC%9A%E7%BC%96%E8%AF%91%E5%99%A8%20%2F%20%E6%B5%8B%E4%BE%8B%20RM%22%5D%0A%20%20GRPO%20--%3E%20LITE%5B%22Lite%2016B-A2.4B%20%C2%B7%20%E5%90%AB%20FIM%22%5D%0A%20%20GRPO%20--%3E%20FULL%5B%22236B-A21B%20%C2%B7%20128K%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="配比是通识保险" tabindex="-1">配比是通识保险 <a class="header-anchor" href="#配比是通识保险" aria-label="Permalink to &quot;配比是通识保险&quot;">​</a></h3><p>60/10/30 让同一套专家既接到 GitHub 的长尾语言，也接到数学网页与通用文本。数学与代码共用符号操作，继续预训练把两条能力一起抬，是报告用 MATH / AIME 与 HumanEval 同时报高分的配比原因；30% 自然语言则是 MMLU 79.2、Arena-Hard 65.0、MT-Bench 8.77、AlignBench 7.84 仍能「像通用模型」的条件——这些主观分用来证明<strong>没有</strong>把 V2 通识训没。相对 V1 的 87% 代码，V2 主动把代码比例降下来，换的是「代码模型也能上 Arena 风格对话」；这是产品定位，不是「代码越少越好」。</p><h3 id="编译器进入-grpo" tabindex="-1">编译器进入 GRPO <a class="header-anchor" href="#编译器进入-grpo" aria-label="Permalink to &quot;编译器进入 GRPO&quot;">​</a></h3><p>GRPO 在代码上的奖励比「像不像人类写的逐步解释」更硬：测例失败则组内相对优势为负。SFT 提供可编译的格式与工具调用习惯，RL 把通过率推上去。128K 服务能成立，前提是 MLA 把 KV 压到可部署（V2 专文的 93.3% 缓存下降是基础设施，不是 Coder 论文新发明的注意力）。语言从 86 到 338 主要是数据覆盖：配置语言、模板、小众脚本出现在 1170B 里，而不是 338 个专家。</p><p>旗舰评测主张（报告口径，须注明基准版本）：HumanEval 90.2%；MBPP 在 EvalPlus 管线上 76.2%；LiveCodeBench（2023-12 至 2024-06）43.4%；SWE-Bench 开源首次超过 10%。MATH 75.7%，接近当时 GPT-4o 的 76.6%，AIME 2024 超过若干闭源表。这些数字描述 236B Instruct 档，不能贴到 Lite。仓库级真实修复刚过 10%，说明 HumanEval 高分与「能改真实 GitHub issue」仍是两回事。</p><p>继续预训练 6T 的优化器与学习率表报告写得比数据配比少，复现成本主要在语料重建与 MoE 集群，而不是抄一条 LR。YaRN 把窗口接到 128K，必须与发布配置里的插值因子一致，否则长文件补全会在后半段失焦。许可证允许商用，但 236B 总参的落盘体积决定了「可下载」不等于「可单机服务」；Lite 才是边侧默认。</p><p><span class="marginnote">「对标 GPT-4 Turbo」写在代码与数学基准上。通用 Arena 风格分数是「没有崩」，不是宣称全面超过 GPT-4o 聊天。Lite 的 HumanEval 再高，也不承担 236B 的 SWE-Bench 叙事。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>236B 总参的部署是 MoE 集群问题：激活 21B 只描述 FLOPs 量级，专家并行、MLA 吸收核、128K KV 缺一则复现不了报告延迟。Lite 适合单机，但 LiveCodeBench / SWE-Bench 叙事属于旗舰。338 语的长尾没有单语充分测例。FIM 在 236B Instruct 上不是默认卖点。数据截止 2023-11，CVE 与新框架会过时。许可 permissive，但专家权重体积使「商用可下」不等于「边侧可跑」。从 V2 中间点继续训，意味着 Coder-V2 的通识上限仍受那份中间检查点约束：6T 代码数学可以加尖，不能把没见过的世界知识变出来。</p><p>不要把 V3 / R1 的无辅助损失与冷启动回写进 Coder-V2。YaRN 与训练长度必须与发布配置一致，否则 128K 只是配置字段。</p><p><span class="marginnote">SWE-Bench 刚过 10% 说明仓库级真实修复仍极难。用 HumanEval 90% 外推「可替代工程师」与报告自己的 SWE 数字矛盾。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Coder-V2 从 V2 中间点继续训 6T，合计约 10.2T；MoE 16B-A2.4B 与 236B-A21B，128K，338 语。</li><li>配比 60% 代码 / 10% 数学 / 30% 自然语言，在抬代码数学的同时保住通识。</li><li>对齐为 SFT + 带编译器反馈的 GRPO；Lite 额外保留 FIM。</li><li>旗舰评测对标当时闭源 Turbo / Opus / Gemini 的代码与数学表，Lite 不可混用。</li><li>出处：Zhu 等，<em>DeepSeek-Coder-V2</em>，arXiv:2406.11931，2024。架构对照 DeepSeek-AI，<em>DeepSeek-V2</em>，arXiv:2405.04434。</li></ul>',14))])}const k=n(E,[["render",h]]);export{P as __pageData,k as default};
